def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max((v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = set()
            while stack:
                y, x = stack.pop()
                comp.add((y, x))
                for yy, xx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            r0 = min(y for y, x in comp)
            r1 = max(y for y, x in comp)
            c0 = min(x for y, x in comp)
            c1 = max(x for y, x in comp)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            border = ({(r0, x) for x in range(c0, c1+1)} |
                      {(r1, x) for x in range(c0, c1+1)} |
                      {(y, c0) for y in range(r0+1, r1)} |
                      {(y, c1) for y in range(r0+1, r1)})
            if comp != border:
                continue
            ih, iw = r1-r0-1, c1-c0-1
            fill = 7 if ih % 2 and iw % 2 else 2
            for y in range(r0+1, r1):
                for x in range(c0+1, c1):
                    if grid[y][x] == bg:
                        out[y][x] = fill
    return out

